// ── Markdown Renderer ─────────────────────────────────────────────────────────

function renderMarkdown(text: string): React.ReactNode {
  const lines = text.split("\n");
  const elements: React.ReactNode[] = [];

  lines.forEach((line, i) => {
    if (line.startsWith("# ")) {
      elements.push(<h2 key={i} className="text-lg font-bold mt-4 mb-2 text-foreground">{line.slice(2)}</h2>);
    } else if (line.startsWith("## ")) {
      elements.push(<h3 key={i} className="text-base font-semibold mt-3 mb-1 text-foreground/90">{line.slice(3)}</h3>);
    } else if (line.startsWith("- ")) {
      const content = line.slice(2);
      // Render inline bold within bullets
      elements.push(
        <li key={i} className="ml-4 text-sm text-muted-foreground list-disc mb-0.5">
          {renderInlineBold(content)}
        </li>
      );
    } else if (line.trim() === "") {
      elements.push(<div key={i} className="h-1" />);
    } else {
      elements.push(<p key={i} className="text-sm text-muted-foreground leading-relaxed mb-1">{renderInlineBold(line)}</p>);
    }
  });

  return <>{elements}</>;
}

function renderInlineBold(text: string): React.ReactNode {
  const parts = text.split(/\*\*(.*?)\*\*/g);
  return parts.map((part, i) =>
    i % 2 === 1
      ? <strong key={i} className="font-semibold text-foreground/90">{part}</strong>
      : part
  );
}

// ── Helper Functions ──────────────────────────────────────────────────────────

function statusBadge(status: ArticleStatus) {
  const cfg: Record<ArticleStatus, { label: string; cls: string }> = {
    published: { label: "Published", cls: "bg-green-500/20 text-green-400" },
    draft: { label: "Draft", cls: "bg-muted text-muted-foreground" },
    review: { label: "In Review", cls: "bg-yellow-500/20 text-yellow-400" },
    archived: { label: "Archived", cls: "bg-muted/50 text-muted-foreground" },
  };
  const { label, cls } = cfg[status];
  return <Badge className={`${cls} border-0 text-xs`}>{label}</Badge>;
}

function helpfulPct(article: Article): number {
  const total = article.helpful + article.notHelpful;
  return total > 0 ? Math.round((article.helpful / total) * 100) : 0;
}

